11	/// What MHPCO records an item as being made of. The office keeps a material
12	/// on every item it insures, but its policy wording singles out only one:
13	/// the rest it records as an ordinary material and draws no distinction
14	/// between them.
15	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
16	pub enum Material {
17	    Dragon,
18	    Ordinary,
19	}
20	
21	impl Material {
22	    /// The material MHPCO recognises under this name. A name the office draws
23	    /// no distinction by -- steel, silver -- is recorded as ordinary.
24	    pub fn named(name: &str) -> Self {
25	        match name {
26	            "dragon" => Self::Dragon,
27	            _ => Self::Ordinary,
28	        }
29	    }
30	}
