32	#[derive(Clone, Copy, Debug)]
33	pub struct Item {
34	    pub item_type: ItemType,
35	    pub material: Material,
36	    pub cursed: bool,
37	    pub enchantment: u32,
38	}
39	
40	impl Item {
41	    pub fn new(item_type: ItemType) -> Self {
42	        Self {
43	            item_type,
44	            material: Material::Ordinary,
45	            cursed: false,
46	            enchantment: 0,
47	        }
48	    }
49	
50	    /// The material MHPCO records the item as being made of.
51	    pub fn made_of(self, material: &str) -> Self {
52	        Self {
53	            material: Material::named(material),
54	            ..self
55	        }
56	    }
57	
58	    pub fn with_enchantment(self, enchantment: u32) -> Self {
59	        Self {
60	            enchantment,
61	            ..self
62	        }
63	    }
